import subprocess

def test_num_rows(num_lines, v):
    text = "a\n" + "\n" * (num_lines - 1) if num_lines > 0 else ""
    p = subprocess.run(["./executable", "-V", str(v)], input=text.encode("utf-8"), capture_output=True)
