use clap::{Arg, ArgAction, Command, value_parser};
use clap_complete::{Shell, generate};
use std::fs::File;
use std::io::{self, Read};
use std::process::exit;

enum Encoding {
    Utf8Lossy,
    Utf8,
}

fn build_cli() -> Command {
    Command::new("code-minimap")
        .version("0.6.8")
        .about("A high performance code minimap generator")
        .disable_version_flag(true)
        .next_line_help(true)
        .arg(
            Arg::new("horizontal_scale")
                .short('H')
                .long("horizontal-scale")
                .value_name("HSCALE")
                .help("Specify horizontal scale factor")
                .default_value("1.0")
                .value_parser(value_parser!(f64)),
        )
        .arg(
            Arg::new("vertical_scale")
                .short('V')
                .long("vertical-scale")
                .value_name("VSCALE")
                .help("Specify vertical scale factor")
                .default_value("1.0")
                .value_parser(value_parser!(f64)),
        )
        .arg(
            Arg::new("padding")
                .long("padding")
                .value_name("PADDING")
                .help("Specify padding width")
                .value_parser(value_parser!(usize)),
        )
        .arg(
            Arg::new("encoding")
                .long("encoding")
                .value_name("ENCODING")
                .help("Specify input encoding")
                .default_value("utf8-lossy")
                .value_parser(["utf8-lossy", "utf8"]),
        )
        .arg(
            Arg::new("version")
                .long("version")
                .help("Print version")
                .action(ArgAction::Version),
        )
        .arg(
            Arg::new("file")
                .value_name("FILE")
                .help("File to read"),
        )
        .subcommand(
            Command::new("completion")
                .about("Generate shell completion file")
                .arg(
                    Arg::new("shell")
                        .value_name("SHELL")
                        .help("Target shell name")
                        .required(true)
                        .value_parser(["bash", "elvish", "fish", "powershell", "zsh"]),
                ),
        )
}

fn main() {
    let matches = build_cli().get_matches();

    if let Some(sub_matches) = matches.subcommand_matches("completion") {
        let shell_str: &String = sub_matches.get_one("shell").unwrap();
        let shell = match shell_str.as_str() {
            "bash" => Shell::Bash,
            "elvish" => Shell::Elvish,
            "fish" => Shell::Fish,
            "powershell" => Shell::PowerShell,
            "zsh" => Shell::Zsh,
            _ => unreachable!(),
        };
        let mut cmd = build_cli();
        generate(shell, &mut cmd, "code-minimap", &mut io::stdout());
        return;
    }

    let h_scale: f64 = *matches.get_one("horizontal_scale").unwrap();
    let v_scale: f64 = *matches.get_one("vertical_scale").unwrap();
    let padding: Option<usize> = matches.get_one("padding").copied();
    let encoding_str: &String = matches.get_one("encoding").unwrap();
    let encoding = if encoding_str == "utf8" {
        Encoding::Utf8
    } else {
        Encoding::Utf8Lossy
    };
    let file_path: Option<&String> = matches.get_one("file");

    let mut raw_bytes = Vec::new();
    if let Some(path) = file_path {
        match File::open(path) {
            Ok(mut f) => {
                if let Err(err) = f.read_to_end(&mut raw_bytes) {
                    eprintln!("code-minimap: {}", err);
                    exit(1);
                }
            }
            Err(err) => {
                eprintln!("code-minimap: {}", err);
                exit(1);
            }
        }
    } else {
        if let Err(err) = io::stdin().read_to_end(&mut raw_bytes) {
            eprintln!("code-minimap: {}", err);
            exit(1);
        }
    }

    let content: String = match encoding {
        Encoding::Utf8 => match String::from_utf8(raw_bytes) {
            Ok(s) => s,
            Err(_) => {
                eprintln!("code-minimap: stream did not contain valid UTF-8");
                exit(1);
            }
        },
        Encoding::Utf8Lossy => String::from_utf8_lossy(&raw_bytes).into_owned(),
    };

    let lines: Vec<&str> = content.lines().collect();
    if lines.is_empty() {
        return;
    }

    let num_lines = lines.len();
    let v_eff = v_scale.min(1.0);
    let last_sub_row = ((num_lines - 1) as f64 * v_eff) as usize;
    let num_rows = (last_sub_row / 4) + 1;

    let mut sub_rows: Vec<Vec<bool>> = Vec::new();

    for (i, line) in lines.iter().enumerate() {
        let sub_row = (i as f64 * v_eff) as usize;

        let mut first_non_ws = None;
        let mut last_non_ws = None;

        for (byte_idx, c) in line.char_indices() {
            if !c.is_whitespace() {
                if first_non_ws.is_none() {
                    first_non_ws = Some(byte_idx);
                }
                last_non_ws = Some(byte_idx);
            }
        }

        if let (Some(start), Some(last)) = (first_non_ws, last_non_ws) {
            let end = last + 1;
            let s_start = (start as f64 * h_scale) as usize;
            let s_end = (end as f64 * h_scale) as usize;

            if sub_row >= sub_rows.len() {
                sub_rows.resize(sub_row + 1, Vec::new());
            }
            if s_end > sub_rows[sub_row].len() {
                sub_rows[sub_row].resize(s_end, false);
            }
            for col in s_start..s_end {
                sub_rows[sub_row][col] = true;
            }
        }
    }

    for r in 0..num_rows {
        let sr0 = 4 * r + 0;
        let sr1 = 4 * r + 1;
        let sr2 = 4 * r + 2;
        let sr3 = 4 * r + 3;

        let get_pixel = |sr: usize, c: usize| -> bool {
            if sr < sub_rows.len() && c < sub_rows[sr].len() {
                sub_rows[sr][c]
            } else {
                false
            }
        };

        let max_col = [sr0, sr1, sr2, sr3]
            .into_iter()
            .filter_map(|sr| {
                if sr < sub_rows.len() {
                    sub_rows[sr].iter().rposition(|&p| p)
                } else {
                    None
                }
            })
            .max();

        let num_blocks = match max_col {
            Some(mc) => (mc / 2) + 1,
            None => 1,
        };

        let mut blocks = Vec::with_capacity(num_blocks);
        for b in 0..num_blocks {
            let c0 = 2 * b + 0;
            let c1 = 2 * b + 1;

            let mut code = 0x2800;

            if get_pixel(sr0, c0) { code |= 0x01; }
            if get_pixel(sr0, c1) { code |= 0x08; }

            if get_pixel(sr1, c0) { code |= 0x02; }
            if get_pixel(sr1, c1) { code |= 0x10; }

            if get_pixel(sr2, c0) { code |= 0x04; }
            if get_pixel(sr2, c1) { code |= 0x20; }

            if get_pixel(sr3, c0) { code |= 0x40; }
            if get_pixel(sr3, c1) { code |= 0x80; }

            blocks.push(char::from_u32(code).unwrap());
        }

        let mut row_str: String = blocks.into_iter().collect();
        if let Some(pad) = padding {
            let char_count = row_str.chars().count();
            if char_count < pad {
                for _ in 0..(pad - char_count) {
                    row_str.push(' ');
                }
            }
        }
        println!("{}", row_str);
    }
}
EOF
cd test_cli && cargo build --offline"}

